INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (148, 231, 'General Documents of normal cargo for exporting business', '../', '<p></p><p style="color:#000000;text-indent:0px;"> General Documents of normal cargo for exporting business/基本单据</p> <p style="color:#000000;text-indent:0px;"> 1. 箱单 packing list</p> <p style="color:#000000;text-indent:0px;"> 2. 发票 invoice</p> <p style="color:#000000;text-indent:0px;"> 3. 合同 contract</p> <p style="color:#000000;text-indent:0px;"> 4. 提单 B/L</p> <p style="color:#000000;text-indent:0px;"> 5. 一般原产地证 CO (certificate of original)</p> <p style="color:#000000;text-indent:0px;"> 6. 技术参数 technology data</p> <p style="color:#000000;text-indent:0px;"> 7. 价格单子 price list</p> <p style="color:#000000;text-indent:0px;"> 8. 安全技术说明书 (MSDS )</p> <p style="color:#000000;text-indent:0px;"> 9. 货物明细单子（each rolls details sheets）</p> <p style="color:#000000;text-indent:0px;"> 10. 空白纸盖章 （blank stamped paper）</p> <p style="color:#000000;text-indent:0px;"> 11. 用途单（Usages/application of this film）</p> <p style="color:#000000;text-indent:0px;"> 12. 购买保险（ CIF ，保险单/insurance policy ）</p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (148, 315, 'HS code number of several products', '../upload/image/20180904/20180904164117_22189.jpg', '<p></p><p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><strong>HS code number of several products</strong></span></p> <p><span style="color:#E53333;font-size:18px;">BOPET HS海关编码是 ? 3920620000</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPP Film H.S.Code number/海关HS编码是？ 39202090.90</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">BOPP tape H.S.Code number/胶带的HS海关编码是多少？ 39199090(00)</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-size:18px;">BOPP 预涂膜的海关HS编码多少？3920109090</span></span></p> <p></p> <p><span style="color:#E53333;font-size:18px;">BOPS 海关编码是: 3903191000</span></p> <p><span style="color:#E53333;font-size:18px;">BOPA HS code NO.: 39209990 密度是：1.04</span></p> <p><span style="color:#E53333;font-size:18px;">POF <span style="color:#E53333;font-size:18px;">HS code NO.: 3926909090 </span></span></p> <p><br/></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">CPP FILM H.S.Code number/ /海关HS编码是？39202090</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">不干胶标签纸 HS: 48219000</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">碳带 HS: 96121000</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">美纹纸胶带母卷的海关HS编码多少？ 48114100</span></p> <p><span style="color:#E53333;font-family:Tahoma;font-size:18px;">复印纸 H.S. code : 4802560090</span></p> <p><br/></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (148, 398, 'Usful knowledge 01', '../', '<p><span style="color:#000000;background-color:#FFFFFF;">电放提单 TELEX RELEASED of &nbsp;B/L &nbsp;(surrender B/L)</span> <p style="color:#000000;text-indent:0px;"> 技术参数 technical data</p> <p style="color:#000000;text-indent:0px;"> 利润微薄 &nbsp;you see , our profit margin is very narrow</p> <p style="color:#000000;text-indent:0px;"> 前半周 前半月 the earlier part of nest week /March month.</p> <p style="color:#000000;text-indent:0px;"> the latter part of nest week /March month.</p> <p style="color:#000000;text-indent:0px;"> 报价仅作参考</p> <p style="color:#000000;text-indent:0px;"> the quotation submitted to you yesterday were offers for reference purpose only.</p> <p style="color:#000000;text-indent:0px;"> 如果方便&nbsp;&nbsp; if it is not so much trouble == if convenience</p> <p style="color:#000000;text-indent:0px;"> 想尽一切办法&nbsp;&nbsp; by every means</p> <p style="color:#000000;text-indent:0px;"> we will try by every means possible to meet your requirements.</p> <p style="color:#000000;text-indent:0px;"> 几近努力后， 接受（ 或者）自己降价</p> <p style="color:#000000;text-indent:0px;"> I am persuade the manager to let transaction successly come to conclusion . and he accept your target price ( make an exception/concession with an eye to future business.)</p> <p style="color:#000000;text-indent:0px;"> 长途海运 long-distance ocean transportation</p> <p style="color:#000000;text-indent:0px;"> 不晚于 not later than</p> <p style="color:#000000;text-indent:0px;"> The quality and performance of our goods can stand every possible test.</p> <p style="color:#000000;text-indent:0px;"> 供你参考 for you look over= for your reference</p> <p style="color:#000000;text-indent:0px;"> 这适合我 that suit me fine</p> <p style="color:#000000;text-indent:0px;"> 纸箱 corrugated cardboard boxes （纸箱加荆条 或者铁片条 reinforce the cartons with metal straps)</p> <p style="color:#000000;text-indent:0px;"> and packing must be seaworthy as well as enough to stand shock and rough handling.</p> <p style="color:#000000;text-indent:0px;"> 连接词，又 &nbsp;additionally, one more thing , plus, another thing,</p> <p style="color:#000000;text-indent:0px;"> Regarding to, As for, For , in compliance with</p> <p style="color:#000000;text-indent:0px;"> 对什么有信心 &nbsp;have great confident in sth</p> <p style="color:#000000;text-indent:0px;"> 有问题 友好协商 if there should be any disputes, we wish to have them settled through firendly discussion.</p> <br class="Apple-interchange-newline" /> <span><span style="color:#3A3A3A;font-family:&quot;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;">上海检验检疫局 Shanghai inspection and Quarantine Bureau</span><br/> <span style="color:#3A3A3A;">中国海关 China Customs</span></span> <br/> <br/> <p><br/></p> <p><span style="color:#000000;background-color:#FFFFFF;"><br/> </span></p> <p><span style="color:#000000;background-color:#FFFFFF;"><br/> </span></p>', '2026-09-06 20:58:45');
INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (148, 399, 'Usful knowledge 02', '../', '<p><p style="color:#000000;text-indent:0px;"> 催促客人支付新订单的定金说：</p> <p style="color:#000000;text-indent:0px;"> Please kindly adv. did you paid to us the deposit for order, if yes, please keen send us the bank SWIFT slip for reference, so that we will have enough time to make all the necessary arrangements.</p> <p style="color:#000000;text-indent:0px;"> <p style="color:#000000;text-indent:0px;"> 给客人降价说：</p> <p style="color:#000000;text-indent:0px;"> considerating that you are our old buyer, In order to encourage future business and as a gesture of friendship ,we are preapred to cut our price( making 5% concession) by 5% .</p> <p style="color:#000000;text-indent:0px;"> <br/></p> <p style="color:#000000;text-indent:0px;"> 价格涨跌，价格趋势 &nbsp;涨：the upward trend, gone up a great deal in recent weeks. &nbsp;the cost of production has been skyrocketing in recent months ,the rising tendency in world market .</p> <p style="color:#000000;text-indent:0px;"> market has been quite strong for sometime and the prevailing price in China keep on rising recently. ( prevailing market price)</p> <p style="color:#000000;text-indent:0px;"> <br/></p> <p style="color:#000000;text-indent:0px;"> 跌： decline trend</p> <p style="color:#000000;text-indent:0px;"> 接你询盘，报价如下： in reply to your inquiry dated " " , we hereby quote you our best price following:</p> <p style="color:#000000;text-indent:0px;"> 对事情没做好，抱歉 &nbsp; please accept our apologies for our inability to do sth.</p> <p style="color:#000000;text-indent:0px;"> 被动： passive situation =awkward position</p> <p style="color:#000000;text-indent:0px;"> 一旦收到钱，立刻出货， goods will be sent upon receipt of your payment</p> <p style="color:#000000;text-indent:0px;"> 另外邮件你 by separate e-mail</p> <br class="Apple-interchange-newline" /> <br/></p>', '2026-09-06 20:58:45');